from solution import check_if_last_char_is_a_letter
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def ref(txt: str) -> bool:
    # Obviously-correct reference derived from spec:
    # True iff non-empty, last char isalpha, and last char is not
    # part of a word where word = group separated by ' ' (literal space).
    # So isolated means at start of string or preceded by ' '.
    if len(txt) == 0:
        return False
    last = txt[-1]
    if not last.isalpha():
        return False
    if len(txt) == 1:
        return True
    if txt[-2] == " ":
        return True
    return False


# ---- concrete examples from spec ----

def test_spec_example_apple_pie_is_false():
    assert check_if_last_char_is_a_letter("apple pie") is False


def test_spec_example_apple_pi_e_is_true():
    assert check_if_last_char_is_a_letter("apple pi e") is True


def test_spec_example_trailing_space_is_false():
    assert check_if_last_char_is_a_letter("apple pi e ") is False


def test_spec_example_empty_is_false():
    assert check_if_last_char_is_a_letter("") is False


# ---- space is the only separator per spec ----

def test_tab_does_not_separate_words_single():
    # No ' ' present, so "a\tb" is one word; last char is part of a word.
    assert check_if_last_char_is_a_letter("a\tb") is False


def test_tab_does_not_separate_words_prefix():
    assert check_if_last_char_is_a_letter("apple\t e") is False


def test_tab_alone_does_not_isolate():
    assert check_if_last_char_is_a_letter("\ta") is False


def test_newline_does_not_separate_words():
    assert check_if_last_char_is_a_letter("a\nb") is False


def test_carriage_return_does_not_separate_words():
    assert check_if_last_char_is_a_letter("a\rb") is False


def test_mixed_whitespace_without_space_is_one_word():
    assert check_if_last_char_is_a_letter("ab\tc") is False
    assert check_if_last_char_is_a_letter("ab\nc") is False
    assert check_if_last_char_is_a_letter("ab\rc") is False


def test_vertical_tab_formfeed_do_not_separate():
    assert check_if_last_char_is_a_letter("ab\vc") is False
    assert check_if_last_char_is_a_letter("ab\fc") is False


# ---- properties ----

@given(st.text(alphabet=st.sampled_from(["a", "b", "c", "Z", "\t", "\n", "\r", "1", "!"]), min_size=2, max_size=10))
def test_property_no_space_multichar_ending_alpha_is_false(txt):
    # If there is no literal space and length > 1, whole string is one word,
    # so a trailing alpha char is part of that word => False.
    assume(" " not in txt)
    assume(len(txt) > 1)
    assume(txt[-1].isalpha())
    assert check_if_last_char_is_a_letter(txt) is False


@given(st.text(alphabet=st.characters(blacklist_categories=("Cs",)), min_size=0, max_size=20))
def test_property_agrees_with_space_only_reference_model(txt):
    assert check_if_last_char_is_a_letter(txt) == ref(txt)


@given(st.text(alphabet=st.characters(blacklist_categories=("Cs",)), min_size=0, max_size=20))
def test_property_trailing_space_always_false(txt):
    assume(len(txt) > 0)
    assume(txt[-1] == " ")
    assert check_if_last_char_is_a_letter(txt) is False


@given(st.text(alphabet=st.characters(blacklist_categories=("Cs",)), min_size=1, max_size=20))
def test_property_non_alpha_last_char_always_false(txt):
    assume(not txt[-1].isalpha())
    assert check_if_last_char_is_a_letter(txt) is False


@given(st.text(alphabet=st.sampled_from(["a", "b", "Z", "x", "y"]), min_size=1, max_size=8))
def test_property_space_isolated_letter_is_true(prefix):
    # prefix + " " + single letter => last char isolated by space => True
    letter = "e"
    txt = prefix + " " + letter
    assert check_if_last_char_is_a_letter(txt) is True


def test_property_single_letter_strings_are_true():
    assert check_if_last_char_is_a_letter("a") is True
    assert check_if_last_char_is_a_letter("Z") is True
    assert check_if_last_char_is_a_letter("k") is True
